const $=(selector,root=document)=>root.querySelector(selector);
const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
const cfg=window.MUGHAL_CONFIG||{};
const cloud=Boolean(cfg.supabaseUrl&&cfg.supabasePublishableKey);
const state={token:null,userId:null,businessId:null,business:null,role:'owner',parties:[],projects:[],entries:[],invoices:[],paymentAccounts:[],payments:[],labourers:[],labourAssignments:[],labourWageSettlements:[],labourWageSettlementItems:[],materials:[],materialMovements:[],expenseCategories:[],walkInOrders:[],walkInEntries:[],orderItems:[],orderInvoiceItems:[],suppliers:[],purchaseBills:[],purchaseBillItems:[],detail:null};
const today=()=>new Date().toISOString().slice(0,10);
const uid=()=>crypto.randomUUID();
const esc=(value='')=>String(['Not entered','Not set','No details','Speciality not set','No account number'].includes(String(value??''))?'':value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const money=value=>`Rs. ${Number(value||0).toLocaleString('en-PK',{maximumFractionDigits:2})}`;
const lineAmount=(quantity,rate)=>Math.round(Number(quantity||0)*Number(rate||0)*100)/100;
const qty=value=>Number(value||0).toLocaleString('en-PK',{maximumFractionDigits:3});
const date=value=>value?new Date(`${String(value).slice(0,10)}T00:00:00`).toLocaleDateString('en-PK',{day:'numeric',month:'short',year:'numeric'}):'';
const daysBetween=(start,end)=>start&&end?Math.max(0,Math.round((new Date(`${end}T00:00:00`)-new Date(`${start}T00:00:00`))/86400000)):'';
const nextSerial=(prefix,rows,field)=>{const values=rows.map(row=>String(row[field]||'')).map(value=>Number(value.match(/(\d+)$/)?.[1]||0));return`${prefix}-${String(Math.max(0,...values)+1).padStart(4,'0')}`;};
const shortCode=(prefix,value)=>`${prefix}-${String(value||'NEW').replaceAll('-','').slice(0,8).toUpperCase()}`;
const safeName=value=>String(value||'document').replace(/[^a-z0-9_-]+/gi,'-').replace(/^-|-$/g,'').toLowerCase();
const PRINT_BUSINESS_NAME='Mughal Interior and Decor';
function setScreenHeader(screen,title){$('.topbar').setAttribute('data-screen',screen);$('#screenTitle').textContent=title;}
const DEFAULT_DISCLAIMER='Prices are subject to change until approval and advance payment. After approval, prices remain fixed unless scope of work or material/site costs change.';
const documentDisclaimer=()=>String(state.business?.document_disclaimer||DEFAULT_DISCLAIMER);
const businessContact=()=>`<div class="business-contact"><p class="business-address"><b>Proprietor Ali Raza Mughal</b><span>Akbar Road Basti Iqbal Nagar,<br>Near Potato Society, Okara</span></p><a class="business-whatsapp" href="https://wa.me/923024441235" target="_blank" rel="noopener noreferrer" aria-label="WhatsApp 03024441235"><img src="assets/whatsapp.svg" width="25" height="25" alt="WhatsApp"><span><small>WhatsApp</small><b>03024441235</b></span></a></div>`;
const disclaimerFooter=()=>`<footer class="document-disclaimer" data-disclaimer><div class="disclaimer-toggle" role="button" tabindex="0" data-toggle-disclaimer aria-expanded="false"><span><b>Disclaimer:</b> <i>${esc(documentDisclaimer())}</i></span><span class="disclaimer-actions"><span aria-hidden="true">Tap to read</span><button type="button" class="disclaimer-edit" data-edit-disclaimer aria-label="Edit disclaimer">✎</button></span></div></footer>`;
const party=id=>state.parties.find(row=>row.id===id);
const project=id=>state.projects.find(row=>row.id===id);
const account=id=>state.paymentAccounts.find(row=>row.id===id);
const bankAccounts=()=>state.paymentAccounts.filter(row=>row.account_type==='Bank'&&row.active!==false);
const cashAccounts=()=>state.paymentAccounts.filter(row=>row.account_type==='Cash'&&row.active!==false);
const accountBalance=id=>Number(account(id)?.opening_balance||0)+state.payments.reduce((total,row)=>total+(row.to_account_id===id?Number(row.amount||0):0)-(row.from_account_id===id?Number(row.amount||0):0),0);
const accountHasActivity=id=>state.payments.some(row=>row.from_account_id===id||row.to_account_id===id);
const transferRows=()=>state.payments.filter(row=>row.payment_type==='transfer');
const labourer=id=>state.labourers.find(row=>row.id===id);
const material=id=>state.materials.find(row=>row.id===id);
const expenseCategory=id=>state.expenseCategories.find(row=>row.id===id);
const supplier=id=>state.suppliers.find(row=>row.id===id);
const purchaseBill=id=>state.purchaseBills.find(row=>row.id===id);
const purchaseLines=id=>state.purchaseBillItems.filter(row=>row.purchase_bill_id===id);
const purchaseBalance=row=>Number(row.total_amount||0)-Number(row.amount_paid||0);
const purchaseDue=row=>Math.max(0,purchaseBalance(row));
const supplierBalance=id=>state.purchaseBills.filter(row=>row.supplier_id===id&&row.status==='Posted').reduce((total,row)=>total+purchaseBalance(row),0);
const projectLabel=row=>`${row.name} - ${party(row.party_id)?.name||'Unknown party'}`;
const quotePrice=row=>row.pricing_mode==='both'?`${money(row.price_with_material)} / ${money(row.price_without_material)}`:money(row.pricing_mode==='without_material'?row.price_without_material:row.price_with_material);
const projectMetrics=row=>{const entries=state.entries.filter(item=>item.project_id===row.id),sum=type=>entries.filter(item=>item.entry_type===type).reduce((total,item)=>total+Number(item.amount||0),0),increase=sum('scope_increase'),decrease=sum('scope_decrease'),original=Number(row.original_contract_amount||0);return{entries,increase,decrease,original,revised:original+increase-decrease};};
const projectBalance=row=>projectMetrics(row).revised-state.payments.filter(payment=>payment.payment_type==='customer_receipt'&&payment.project_id===row.id).reduce((sum,payment)=>sum+Number(payment.amount||0),0);
const materialMetrics=row=>{const movements=state.materialMovements.filter(item=>item.material_id===row.id),purchased=movements.filter(item=>['purchase','adjustment_in','walk_in_return','project_return'].includes(item.movement_type)).reduce((sum,item)=>sum+Number(item.quantity||0),0),used=movements.filter(item=>['project_issue','walk_in_issue','adjustment_out'].includes(item.movement_type)).reduce((sum,item)=>sum+Number(item.quantity||0),0),latest=[...movements].filter(item=>item.movement_type==='purchase').sort((a,b)=>`${b.movement_date}${b.created_at}`.localeCompare(`${a.movement_date}${a.created_at}`))[0];return{stock:purchased-used,unitCost:Number(latest?.unit_cost??row.default_unit_cost??0)};};
const walkInOrder=id=>state.walkInOrders.find(row=>row.id===id);
const orderLabel=row=>`${row.order_number} - ${row.customer_name}`;
const orderInvoice=row=>state.invoices.find(invoice=>invoice.walk_in_order_id===row.id);
const orderLines=id=>state.orderInvoiceItems.filter(row=>row.walk_in_order_id===id).sort((a,b)=>Number(a.sort_order)-Number(b.sort_order));
const orderDue=row=>Number(row.amount||0)-state.walkInEntries.filter(entry=>entry.walk_in_order_id===row.id&&entry.entry_type==='receipt').reduce((sum,entry)=>sum+Number(entry.amount||0),0);
const assignmentAmount=row=>Number(row.amount??Number(row.days||0)*Number(row.daily_rate||0));
const assignmentPaidAmount=id=>state.labourWageSettlementItems.filter(row=>row.labour_assignment_id===id).reduce((sum,row)=>sum+Number(row.amount||0),0);
const assignmentOutstanding=row=>Math.max(0,assignmentAmount(row)-assignmentPaidAmount(row.id));
const unpaidAssignments=labourerId=>state.labourAssignments.filter(row=>row.labourer_id===labourerId&&assignmentOutstanding(row)>0.005);
const labourAdvancePaid=labourerId=>state.payments.filter(row=>row.payment_type==='labour_advance'&&row.labourer_id===labourerId).reduce((sum,row)=>sum+Number(row.amount||0),0);
const labourAdvanceApplied=labourerId=>state.labourWageSettlements.filter(row=>row.labourer_id===labourerId).reduce((sum,row)=>sum+Number(row.advance_applied||0),0);
const labourAdvanceAvailable=labourerId=>Math.max(0,labourAdvancePaid(labourerId)-labourAdvanceApplied(labourerId));
const labourUnpaidTotal=labourerId=>unpaidAssignments(labourerId).reduce((sum,row)=>sum+assignmentOutstanding(row),0);
const labourTaskLabel=row=>{const job=project(row.project_id),order=walkInOrder(row.walk_in_order_id);return job?projectLabel(job):order?orderLabel(order):'Assigned task';};

class Store{
  constructor(){this.base=(cfg.supabaseUrl||'').replace(/\/$/,'');this.key=cfg.supabasePublishableKey||'';}
  headers(extra={}){return{apikey:this.key,Authorization:`Bearer ${state.token}`,'Content-Type':'application/json',...extra};}
  async request(path,options={}){const response=await fetch(`${this.base}${path}`,{...options,headers:this.headers(options.headers)});if(response.status===401){logout(false);throw new Error('Your session expired. Please sign in again.');}if(!response.ok){let message='The action could not be completed.';try{const data=await response.json();message=data.message||data.details||data.hint||message;}catch{}throw new Error(message);}return response.status===204?null:response.json();}
  async signIn(email,password){const response=await fetch(`${this.base}/auth/v1/token?grant_type=password`,{method:'POST',headers:{apikey:this.key,'Content-Type':'application/json'},body:JSON.stringify({email,password})}),data=await response.json();if(!response.ok)throw new Error(data.error_description||data.msg||'Email or password is incorrect.');state.token=data.access_token;state.userId=data.user.id;localStorage.setItem('mi_mobile_session',JSON.stringify({token:state.token,userId:state.userId}));}
  async load(){
    if(!cloud){const saved=JSON.parse(localStorage.getItem('mi_mobile_data')||'{}');state.businessId='demo';state.role='owner';state.business=saved.business||{name:'Mughal Interior'};['parties','projects','entries','invoices','paymentAccounts','payments','labourers','labourAssignments','labourWageSettlements','labourWageSettlementItems','materials','materialMovements','expenseCategories','walkInOrders','walkInEntries','orderItems','orderInvoiceItems','suppliers','purchaseBills','purchaseBillItems'].forEach(key=>state[key]=saved[key]||[]);return;}
    const memberships=await this.request(`/rest/v1/business_members?select=business_id,role&user_id=eq.${state.userId}&order=created_at.desc&limit=1`);if(!memberships.length)throw new Error('This account has not been added to a business.');state.businessId=memberships[0].business_id;state.role=memberships[0].role;
    [state.parties,state.projects,state.entries,state.invoices,state.paymentAccounts,state.payments,state.labourers,state.labourAssignments,state.labourWageSettlements,state.labourWageSettlementItems,state.materials,state.materialMovements,state.expenseCategories,state.walkInOrders,state.walkInEntries,state.orderItems,state.orderInvoiceItems,state.suppliers,state.purchaseBills,state.purchaseBillItems]=await Promise.all([
      this.request(`/rest/v1/parties?select=*&business_id=eq.${state.businessId}&order=name.asc`),this.request(`/rest/v1/projects?select=*&business_id=eq.${state.businessId}&order=created_at.desc`),this.request(`/rest/v1/project_entries?select=*&business_id=eq.${state.businessId}&order=entry_date.desc,created_at.desc`),this.request(`/rest/v1/invoices?select=*&business_id=eq.${state.businessId}&order=created_at.desc`),this.request(`/rest/v1/payment_accounts?select=*&business_id=eq.${state.businessId}&active=eq.true&order=name.asc`),this.request(`/rest/v1/payments?select=*&business_id=eq.${state.businessId}&order=payment_date.desc,created_at.desc`),this.request(`/rest/v1/labourers?select=*&business_id=eq.${state.businessId}&order=name.asc`),this.request(`/rest/v1/labour_assignments?select=*&business_id=eq.${state.businessId}&order=assignment_date.desc,created_at.desc`),this.request(`/rest/v1/labour_wage_settlements?select=*&business_id=eq.${state.businessId}&order=settlement_date.desc,created_at.desc`),this.request(`/rest/v1/labour_wage_settlement_items?select=*&business_id=eq.${state.businessId}&order=created_at.desc`),this.request(`/rest/v1/materials?select=*&business_id=eq.${state.businessId}&active=eq.true&order=name.asc`),this.request(`/rest/v1/material_movements?select=*&business_id=eq.${state.businessId}&order=movement_date.desc,created_at.desc`),this.request(`/rest/v1/expense_categories?select=*&business_id=eq.${state.businessId}&active=eq.true&order=name.asc`),this.request(`/rest/v1/walk_in_orders?select=*&business_id=eq.${state.businessId}&order=order_date.desc,created_at.desc`),this.request(`/rest/v1/walk_in_order_entries?select=*&business_id=eq.${state.businessId}&order=entry_date.desc,created_at.desc`),this.request(`/rest/v1/order_items?select=*&business_id=eq.${state.businessId}&active=eq.true&order=name.asc`),this.request(`/rest/v1/order_invoice_items?select=*&business_id=eq.${state.businessId}&order=sort_order.asc`),this.request(`/rest/v1/suppliers?select=*&business_id=eq.${state.businessId}&active=eq.true&order=name.asc`),this.request(`/rest/v1/purchase_bills?select=*&business_id=eq.${state.businessId}&order=bill_date.desc,created_at.desc`),this.request(`/rest/v1/purchase_bill_items?select=*&business_id=eq.${state.businessId}&order=created_at.asc`)
    ]);const businesses=await this.request(`/rest/v1/businesses?select=*&id=eq.${state.businessId}&limit=1`);state.business=businesses[0]||{name:'Mughal Interior'};
  }
  persist(){if(!cloud)localStorage.setItem('mi_mobile_data',JSON.stringify({business:state.business,parties:state.parties,projects:state.projects,entries:state.entries,invoices:state.invoices,paymentAccounts:state.paymentAccounts,payments:state.payments,labourers:state.labourers,labourAssignments:state.labourAssignments,labourWageSettlements:state.labourWageSettlements,labourWageSettlementItems:state.labourWageSettlementItems,materials:state.materials,materialMovements:state.materialMovements,expenseCategories:state.expenseCategories,walkInOrders:state.walkInOrders,walkInEntries:state.walkInEntries,orderItems:state.orderItems,orderInvoiceItems:state.orderInvoiceItems,suppliers:state.suppliers,purchaseBills:state.purchaseBills,purchaseBillItems:state.purchaseBillItems}));}
  async save(table,row,updating=false){if(!cloud)return{...row,business_id:state.businessId,updated_at:new Date().toISOString()};const payload={...row,business_id:state.businessId},path=updating?`/rest/v1/${table}?id=eq.${row.id}`:`/rest/v1/${table}`,result=await this.request(path,{method:updating?'PATCH':'POST',headers:{Prefer:'return=representation'},body:JSON.stringify(payload)});return result[0];}
  async updateBusiness(changes){if(!cloud)return{...state.business,...changes,updated_at:new Date().toISOString()};const result=await this.request(`/rest/v1/businesses?id=eq.${state.businessId}`,{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify(changes)});if(!result?.length)throw new Error('Only an owner or manager can update the print disclaimer.');return result[0];}
  async remove(table,id){if(!cloud)return;const removed=await this.request(`/rest/v1/${table}?id=eq.${id}`,{method:'DELETE',headers:{Prefer:'return=representation'}});if(!removed?.length)throw new Error('Only the business owner can delete this record.');}
  async rpc(name,payload){return this.request(`/rest/v1/rpc/${name}`,{method:'POST',body:JSON.stringify(payload)});}
}
const store=new Store();

function toast(message){const node=$('#toast');node.textContent=message;node.classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.classList.add('hidden'),3200);}
async function working(label,button,action){const overlay=$('#processing'),old=button?.textContent;if(button){button.disabled=true;button.classList.add('processing');button.textContent='Please wait…';}$('#processingText').textContent=label;overlay.classList.remove('hidden');try{return await action();}catch(error){toast(error.message);throw error;}finally{overlay.classList.add('hidden');if(button){button.disabled=false;button.classList.remove('processing');button.textContent=old;}}}
function openSheet(id){$('#backdrop').classList.remove('hidden');$(id).classList.remove('hidden');document.body.style.overflow='hidden';window.MughalControls?.refresh();}
function closeSheets(){$('#backdrop').classList.add('hidden');$$('.sheet').forEach(node=>node.classList.add('hidden'));document.body.style.overflow='';}
function route(name){const map={projectsHub:'Projects',parties:'Parties',projectMaster:'Projects',quotes:'Quotes',invoices:'Invoices',receipts:'Receive payments',labour:'Assign labour',materials:'Assign material',expenses:'Charge expenses',orders:'Orders',orderInvoices:'Order invoices',orderReceipts:'Order receipts',orderExpenses:'Order expenses',orderMaterials:'Order materials',orderLabour:'Order labour',orderItems:'Order items',purchasing:'Purchasing',purchaseSuppliers:'Suppliers',purchaseMaterials:'Material',purchases:'Purchases',purchasePayments:'Purchase payments',labourPayments:'Labour',banking:'Banking',bankAccounts:'List of Banks',cashWithdrawals:'Withdraw cash',cashDeposits:'Deposit cash',bankTransfers:'Bank to Bank',bankingExpenses:'Expenses',reports:'Reports'};$$('.view').forEach(node=>node.classList.toggle('active',node.id===`${name}View`));setScreenHeader(name,map[name]||'Projects');window.scrollTo({top:0,behavior:'instant'});render();}
function tab(name){$$('[data-tab]').forEach(button=>button.classList.toggle('active',button.dataset.tab===name));route(name);}
function empty(title,text){return`<div class="empty"><b>${esc(title)}</b><span>${esc(text)}</span></div>`;}
function upsert(list,row){const index=list.findIndex(item=>item.id===row.id);index>=0?list.splice(index,1,row):list.unshift(row);store.persist();}
function options(rows,label,placeholder='Select an option'){return`<option value="">${esc(placeholder)}</option>${rows.map(row=>`<option value="${row.id}">${esc(label(row))}</option>`).join('')}`;}

function renderParties(){const q=$('#partySearch').value.toLowerCase(),rows=state.parties.filter(r=>[r.party_number,r.name,r.phone,r.address].join(' ').toLowerCase().includes(q));$('#partyList').innerHTML=rows.length?rows.map(r=>`<article class="record-card"><div class="record-top"><div><span class="record-id">${esc(r.party_number||shortCode('PTY',r.id))}</span><h3>${esc(r.name)}</h3><div class="record-meta">${r.phone?`<span>${esc(r.phone)}</span>`:''}${r.address?`<span>${esc(r.address)}</span>`:''}</div></div><button class="view-button" data-view-party="${r.id}">View</button></div></article>`).join(''):empty('No parties found','Add your first customer.');}
function renderProjects(){const q=$('#projectSearch').value.toLowerCase(),rows=state.projects.filter(r=>[r.project_number,r.name,r.location,party(r.party_id)?.name].join(' ').toLowerCase().includes(q));$('#projectList').innerHTML=rows.length?rows.map(r=>`<article class="record-card"><div class="record-top"><div><span class="record-id">${esc(r.project_number||shortCode('PRJ',r.id))}</span><h3>${esc(r.name)}</h3><div class="record-meta"><span>${esc(party(r.party_id)?.name||'Unknown party')}</span>${r.location?`<span>${esc(r.location)}</span>`:''}<span class="status ${r.closed?'closed':'active'}">${r.closed?'Closed':'Active'}</span><span>${r.quote_created?'Quote added':'No quote'}</span></div></div><button class="view-button" data-view-project="${r.id}">View</button></div></article>`).join(''):empty('No projects found','Add a project record to begin.');}
function renderQuotes(){const q=$('#quoteSearch').value.toLowerCase(),rows=state.projects.filter(r=>r.quote_created&&[r.project_number,r.name,party(r.party_id)?.name].join(' ').toLowerCase().includes(q));$('#quoteList').innerHTML=rows.length?rows.map(r=>`<article class="record-card"><div class="record-top"><div><span class="record-id">${esc(r.project_number)}</span><h3>${esc(r.name)}</h3><div class="record-meta"><span>${esc(party(r.party_id)?.name||'Unknown party')}</span><span>${date(r.quote_date)}</span><span>${quotePrice(r)}</span></div></div><div class="record-side"><span class="status ${String(r.status||'pending').toLowerCase()}">${esc(r.status)}</span><button class="view-button" data-view-quote="${r.id}">View</button></div></div></article>`).join(''):empty('No quotes found','Add a quote for a saved project.');}
function renderInvoices(){const q=$('#invoiceSearch').value.toLowerCase(),rows=state.invoices.filter(r=>r.project_id).filter(r=>{const job=project(r.project_id);return[r.invoice_number,job?.name,party(job?.party_id)?.name].join(' ').toLowerCase().includes(q)});$('#invoiceList').innerHTML=rows.length?rows.map(r=>{const job=project(r.project_id),total=job?projectMetrics(job).revised:r.amount;return`<article class="record-card"><div class="record-top"><div><span class="record-id">${esc(r.invoice_number)}</span><h3>${esc(job?.name||'Project invoice')}</h3><div class="record-meta"><span>${esc(party(job?.party_id)?.name||'Unknown party')}</span><span>${date(r.invoice_date)}</span></div></div><div class="record-side"><strong>${money(total)}</strong><button class="view-button" data-view-invoice="${r.id}">View</button></div></div><div class="card-actions"><button class="button secondary block" data-download-invoice="${r.id}">Download PDF</button></div></article>`}).join(''):empty('No invoices found','Approved quotes appear here automatically.');}
function renderReceipts(){const q=$('#receiptSearch').value.toLowerCase(),rows=state.payments.filter(r=>r.payment_type==='customer_receipt'&&r.project_id).filter(r=>{const job=project(r.project_id);return[r.payment_number,r.description,job?.name,party(r.party_id)?.name].join(' ').toLowerCase().includes(q)});$('#receiptList').innerHTML=rows.length?rows.map(r=>{const job=project(r.project_id);return`<article class="record-card"><div class="record-top"><div><span class="record-id">${esc(r.payment_number||shortCode('RCP',r.id))}</span><h3>${esc(job?.name||'Project receipt')}</h3><div class="record-meta"><span>${esc(party(r.party_id)?.name||'Unknown party')}</span><span>${date(r.payment_date)}</span><span>${esc(account(r.to_account_id)?.name||'Account')}</span></div></div><div class="record-side"><strong class="record-total">${money(r.amount)}</strong><button class="view-button" data-view-receipt="${r.id}">View</button></div></div></article>`}).join(''):empty('No payments received','Record the first project receipt.');}
function renderLabour(){$('#labourPersonList').innerHTML=state.labourers.length?state.labourers.map(r=>`<article class="record-card"><div class="record-top"><div><span class="record-id">${esc(r.labour_number||date(r.joining_date||r.record_date||r.created_at))}</span><h3>${esc(r.name)}</h3><div class="record-meta">${r.speciality?`<span>${esc(r.speciality)}</span>`:''}${r.mobile?`<span>${esc(r.mobile)}</span>`:''}<span>${money(r.daily_wage_rate)} daily</span></div></div><button class="view-button" data-view-labour-person="${r.id}">View</button></div></article>`).join(''):empty('No labour persons','Add a labour person before assigning wages.');$('#labourAssignmentList').innerHTML=state.labourAssignments.filter(r=>r.project_id).length?state.labourAssignments.filter(r=>r.project_id).map(r=>{const job=project(r.project_id),worker=labourer(r.labourer_id);return`<article class="record-card"><div class="record-top"><div><span class="record-id">${date(r.assignment_date)}</span><h3>${esc(worker?.name||'Labour')}</h3><div class="record-meta"><span>${esc(job?projectLabel(job):'')}</span><span>${Number(r.days)===.5?'Half day':'Full day'}</span></div></div><div class="record-side"><strong>${money(r.amount??Number(r.days)*Number(r.daily_rate))}</strong><button class="view-button" data-view-labour-assignment="${r.id}">View</button></div></div></article>`}).join(''):empty('No labour assigned','Assign a labour person to an approved project.');}
function renderMaterials(){const q=$('#materialAssignmentSearch').value.toLowerCase(),rows=state.materialMovements.filter(r=>['project_issue','project_return'].includes(r.movement_type)).filter(r=>{const job=project(r.project_id);return[material(r.material_id)?.name,job?.name,party(job?.party_id)?.name,r.notes].join(' ').toLowerCase().includes(q)});$('#materialAssignmentList').innerHTML=rows.length?rows.map(r=>{const item=material(r.material_id),job=project(r.project_id),returned=r.movement_type==='project_return';return`<article class="record-card"><div class="record-top"><div><span class="record-id">${date(r.movement_date)}</span><h3>${esc(item?.name||'Material')} <span class="inline-badge">${returned?'Returned':'Assigned'}</span></h3><div class="record-meta"><span>${esc(job?projectLabel(job):'')}</span><span>${qty(r.quantity)} ${esc(item?.unit||'units')}</span></div></div><div class="record-side"><strong class="${returned?'positive':''}">${returned?'+':'−'} ${money(Number(r.quantity)*Number(r.unit_cost))}</strong><button class="view-button" data-view-material-assignment="${r.id}">View</button></div></div></article>`}).join(''):empty('No material activity','Assign purchased material or record a return.');}
function renderExpenses(){$('#expenseCategoryList').innerHTML=state.expenseCategories.length?state.expenseCategories.map(r=>`<article class="record-card"><div class="record-top"><div><span class="record-id">EXPENSE MASTER</span><h3>${esc(r.name)}</h3><div class="record-meta"><span>${esc(r.description||'No details')}</span></div></div><button class="view-button" data-view-expense-category="${r.id}">View</button></div></article>`).join(''):empty('No expense types','Add the first project expense type.');const charges=state.entries.filter(r=>r.entry_type==='expense');$('#expenseChargeList').innerHTML=charges.length?charges.map(r=>{const job=project(r.project_id),cat=expenseCategory(r.expense_category_id);return`<article class="record-card"><div class="record-top"><div><span class="record-id">${date(r.entry_date)}</span><h3>${esc(cat?.name||r.description)}</h3><div class="record-meta"><span>${esc(job?projectLabel(job):'Project')}</span>${r.notes?`<span>${esc(r.notes)}</span>`:''}</div></div><div class="record-side"><strong>${money(r.amount)}</strong><button class="view-button" data-view-expense-charge="${r.id}">View</button></div></div></article>`}).join(''):empty('No expenses charged','Charge an expense to an approved project.');}
function renderOrderInvoices(){const q=$('#orderInvoiceSearch').value.toLowerCase(),rows=state.walkInOrders.filter(r=>orderInvoice(r)).filter(r=>[r.order_number,r.customer_name,r.customer_phone,orderInvoice(r)?.invoice_number].join(' ').toLowerCase().includes(q));$('#orderInvoiceList').innerHTML=rows.length?rows.map(r=>{const invoice=orderInvoice(r);return`<article class="record-card"><div class="record-top"><div><span class="record-id">${esc(invoice?.invoice_number||r.order_number)}</span><h3>${esc(r.customer_name)}</h3><div class="record-meta"><span>${date(invoice?.invoice_date||r.order_date)}</span>${r.customer_phone?`<span>${esc(r.customer_phone)}</span>`:''}<span>${orderLines(r.id).length} items</span></div></div><div class="record-side"><strong>${money(r.amount)}</strong><button class="view-button" data-view-order-invoice="${r.id}">View</button></div></div></article>`}).join(''):empty('No order invoices','Create the first direct customer invoice.');}
function renderOrderReceipts(){const q=$('#orderReceiptSearch').value.toLowerCase(),rows=state.payments.filter(r=>r.payment_type==='customer_receipt'&&r.walk_in_order_id).filter(r=>{const order=walkInOrder(r.walk_in_order_id);return[r.payment_number,r.description,order?.order_number,order?.customer_name].join(' ').toLowerCase().includes(q)});$('#orderReceiptList').innerHTML=rows.length?rows.map(r=>{const order=walkInOrder(r.walk_in_order_id);return`<article class="record-card"><div class="record-top"><div><span class="record-id">${esc(r.payment_number)}</span><h3>${esc(order?.customer_name||'Order receipt')}</h3><div class="record-meta"><span>${esc(order?.order_number||'Order')}</span><span>${date(r.payment_date)}</span><span>${esc(account(r.to_account_id)?.name||'Account')}</span></div></div><div class="record-side"><strong class="record-total">${money(r.amount)}</strong><button class="view-button" data-view-order-receipt="${r.id}">View</button></div></div></article>`}).join(''):empty('No order receipts','Receive the first payment against an order.');}
function renderOrderExpenses(){$('#orderExpenseCategoryList').innerHTML=$('#expenseCategoryList').innerHTML;const rows=state.walkInEntries.filter(r=>r.entry_type==='expense');$('#orderExpenseChargeList').innerHTML=rows.length?rows.map(r=>{const order=walkInOrder(r.walk_in_order_id),cat=expenseCategory(r.expense_category_id);return`<article class="record-card"><div class="record-top"><div><span class="record-id">${date(r.entry_date)}</span><h3>${esc(cat?.name||r.description)}</h3><div class="record-meta"><span>${esc(order?orderLabel(order):'Order')}</span>${r.notes?`<span>${esc(r.notes)}</span>`:''}</div></div><div class="record-side"><strong>${money(r.amount)}</strong><button class="view-button" data-view-order-expense="${r.id}">View</button></div></div></article>`}).join(''):empty('No order expenses','Assign an expense to an order.');}
function renderOrderMaterials(){const q=$('#orderMaterialSearch').value.toLowerCase(),rows=state.materialMovements.filter(r=>['walk_in_issue','walk_in_return'].includes(r.movement_type)).filter(r=>{const order=walkInOrder(r.walk_in_order_id);return[material(r.material_id)?.name,order?.customer_name,order?.order_number,r.notes].join(' ').toLowerCase().includes(q)});$('#orderMaterialList').innerHTML=rows.length?rows.map(r=>{const order=walkInOrder(r.walk_in_order_id),item=material(r.material_id),returned=r.movement_type==='walk_in_return';return`<article class="record-card"><div class="record-top"><div><span class="record-id">${date(r.movement_date)}</span><h3>${esc(item?.name||'Material')} <span class="inline-badge">${returned?'Returned':'Assigned'}</span></h3><div class="record-meta"><span>${esc(order?orderLabel(order):'Order')}</span><span>${qty(r.quantity)} ${esc(item?.unit||'units')}</span></div></div><div class="record-side"><strong class="${returned?'positive':''}">${returned?'+':'−'} ${money(Number(r.quantity)*Number(r.unit_cost))}</strong><button class="view-button" data-view-order-material="${r.id}">View</button></div></div></article>`}).join(''):empty('No order material activity','Assign purchased material or record a return.');}
function renderOrderLabour(){$('#orderLabourPersonList').innerHTML=$('#labourPersonList').innerHTML;const rows=state.labourAssignments.filter(r=>r.walk_in_order_id);$('#orderLabourAssignmentList').innerHTML=rows.length?rows.map(r=>{const order=walkInOrder(r.walk_in_order_id),worker=labourer(r.labourer_id);return`<article class="record-card"><div class="record-top"><div><span class="record-id">${date(r.assignment_date)}</span><h3>${esc(worker?.name||'Labour')}</h3><div class="record-meta"><span>${esc(order?orderLabel(order):'Order')}</span><span>${Number(r.days)===.5?'Half day':'Full day'}</span></div></div><div class="record-side"><strong>${money(r.amount??Number(r.days)*Number(r.daily_rate))}</strong><button class="view-button" data-view-order-labour="${r.id}">View</button></div></div></article>`}).join(''):empty('No order labour assigned','Assign a labour person to an order.');}
function renderOrderItems(){const q=$('#orderItemSearch').value.toLowerCase(),rows=state.orderItems.filter(r=>[r.name,r.details].join(' ').toLowerCase().includes(q));$('#orderItemList').innerHTML=rows.length?rows.map(r=>`<article class="record-card"><div class="record-top"><div><span class="record-id">INVOICE ITEM</span><h3>${esc(r.name)}</h3><div class="record-meta"><span>${esc(r.details||'No details')}</span></div></div><button class="view-button" data-view-order-item="${r.id}">View</button></div></article>`).join(''):empty('No invoice items','Add items such as tables, doors or cupboards.');}
function renderOrders(){renderOrderInvoices();renderOrderReceipts();renderOrderExpenses();renderOrderMaterials();renderOrderLabour();renderOrderItems();$('#orderCustomerPhoneOptions').innerHTML=[...new Map(state.walkInOrders.filter(r=>r.customer_phone).map(r=>[r.customer_phone,r])).values()].map(r=>`<option value="${esc(r.customer_phone)}">${esc(r.customer_name)}</option>`).join('');}
function renderPurchaseSuppliers(){const q=$('#supplierSearch').value.toLowerCase(),rows=state.suppliers.filter(r=>[r.supplier_number,r.name,r.company_name,r.phone,r.address,r.notes].join(' ').toLowerCase().includes(q));$('#supplierList').innerHTML=rows.length?rows.map(r=>`<article class="record-card"><div class="record-top"><div><span class="record-id">${esc(r.supplier_number||shortCode('SUP',r.id))}</span><h3>${esc(r.name)}</h3><div class="record-meta">${r.company_name?`<span>${esc(r.company_name)}</span>`:''}${r.phone?`<span>${esc(r.phone)}</span>`:''}<span>${state.purchaseBills.filter(b=>b.supplier_id===r.id).length} purchases</span></div></div><button class="view-button" data-view-supplier="${r.id}">View</button></div></article>`).join(''):empty('No suppliers found','Add the first material supplier.');}
function renderPurchaseMaterials(){const q=$('#purchaseMaterialSearch').value.toLowerCase(),rows=state.materials.filter(r=>[r.name,r.sku,r.unit,r.details].join(' ').toLowerCase().includes(q));$('#purchaseMaterialList').innerHTML=rows.length?rows.map(r=>{const metric=materialMetrics(r);return`<article class="record-card"><div class="record-top"><div><span class="record-id">${esc(r.sku||shortCode('MAT',r.id))}</span><h3>${esc(r.name)}</h3><div class="record-meta"><span>${qty(metric.stock)} ${esc(r.unit)} in stock</span><span>${money(metric.unitCost)} latest cost</span></div></div><button class="view-button" data-view-purchase-material="${r.id}">View</button></div></article>`}).join(''):empty('No materials found','Add material before recording a purchase.');}
function renderPurchases(){const q=$('#purchaseSearch').value.toLowerCase(),rows=state.purchaseBills.filter(r=>{const vendor=supplier(r.supplier_id),names=purchaseLines(r.id).map(line=>material(line.material_id)?.name);return[r.bill_number,vendor?.name,vendor?.company_name,...names].join(' ').toLowerCase().includes(q)});$('#purchaseList').innerHTML=rows.length?rows.map(r=>{const vendor=supplier(r.supplier_id);return`<article class="record-card"><div class="record-top"><div><span class="record-id">${esc(r.bill_number)}</span><h3>${esc(vendor?.name||'Supplier purchase')}</h3><div class="record-meta"><span>${date(r.bill_date)}</span><span>${purchaseLines(r.id).length} materials</span><span>${esc(r.payment_status)}</span></div></div><div class="record-side"><strong>${money(r.total_amount)}</strong><button class="view-button" data-view-purchase="${r.id}">View</button></div></div></article>`}).join(''):empty('No purchases found','Record the first material purchase.');}
function renderPurchasePayments(){const q=$('#purchasePaymentSearch').value.toLowerCase(),rows=state.payments.filter(r=>r.payment_type==='supplier_payment').filter(r=>{const vendor=supplier(r.supplier_id),bill=purchaseBill(r.purchase_bill_id);return[r.payment_number,r.description,vendor?.name,vendor?.company_name,bill?.bill_number].join(' ').toLowerCase().includes(q)});$('#purchasePaymentList').innerHTML=rows.length?rows.map(r=>{const vendor=supplier(r.supplier_id),bill=purchaseBill(r.purchase_bill_id);return`<article class="record-card"><div class="record-top"><div><span class="record-id">${esc(r.payment_number)}</span><h3>${esc(vendor?.name||'Supplier payment')}</h3><div class="record-meta"><span>${esc(bill?.bill_number||'Overall supplier account')}</span><span>${date(r.payment_date)}</span><span>${esc(account(r.from_account_id)?.name||'Account')}</span></div></div><div class="record-side"><strong>${money(r.amount)}</strong><button class="view-button" data-view-purchase-payment="${r.id}">View</button></div></div></article>`}).join(''):empty('No purchase payments','Record the first supplier payment.');}
function renderPurchasing(){renderPurchaseSuppliers();renderPurchaseMaterials();renderPurchases();renderPurchasePayments();}
function renderLabourPayments(){const balances=state.labourers.map(worker=>{const unpaid=labourUnpaidTotal(worker.id),advance=labourAdvanceAvailable(worker.id);return{worker,unpaid,advance,net:Math.max(0,unpaid-advance)}}).filter(row=>row.unpaid>0||row.advance>0);$('#labourBalanceList').innerHTML=balances.length?balances.map(row=>`<article class="record-card"><div class="record-top"><div><span class="status ${row.unpaid>0?'wage-due':'advance-credit'}">${row.unpaid>0?'WAGES DUE':'ADVANCE CREDIT'}</span><h3>${esc(row.worker.name)}</h3><div class="record-meta"><span class="wage-due-text">Wages due ${money(row.unpaid)}</span><span class="advance-credit-text">Advance balance ${money(row.advance)}</span><span>Net payable ${money(row.net)}</span></div></div>${row.unpaid>0?`<button class="view-button" data-pay-worker="${row.worker.id}">Pay wages</button>`:''}</div></article>`).join(''):empty('No labour balances','Assignments and advances will appear here.');const history=[...state.labourWageSettlements.map(row=>({kind:'wage',id:row.id,labourer_id:row.labourer_id,date:row.settlement_date,amount:row.gross_wages,created_at:row.created_at})),...state.payments.filter(row=>row.payment_type==='labour_advance').map(row=>({kind:'advance',id:row.id,labourer_id:row.labourer_id,date:row.payment_date,amount:row.amount,created_at:row.created_at}))].sort((a,b)=>`${b.date}${b.created_at}`.localeCompare(`${a.date}${a.created_at}`));$('#labourPaymentHistory').innerHTML=history.length?history.map(row=>`<article class="record-card"><div class="record-top"><div><span class="status ${row.kind==='wage'?'wage-due':'advance-credit'}">${row.kind==='wage'?'WAGE SETTLEMENT':'ADVANCE PAYMENT'}</span><h3>${esc(labourer(row.labourer_id)?.name||'Labour')}</h3><div class="record-meta"><span>${date(row.date)}</span><span>${row.kind==='wage'?'Wages settled':'Advance recorded'}</span></div></div><div class="record-side"><strong>${money(row.amount)}</strong><button class="view-button" data-view-labour-${row.kind}="${row.id}">View</button></div></div></article>`).join(''):empty('No labour payments','Wage settlements and advances will appear here.');}
function transferCard(row){const from=account(row.from_account_id),to=account(row.to_account_id);return`<article class="record-card"><div class="record-top"><div><span class="record-id">${esc(row.payment_number||shortCode('TRF',row.id))}</span><h3>${esc(from?.name||'Account')} → ${esc(to?.name||'Account')}</h3><div class="record-meta"><span>${date(row.payment_date)}</span><span>${esc(row.description||'Money transfer')}</span></div></div><div class="record-side"><strong>${money(row.amount)}</strong><button class="view-button" data-view-bank-transfer-entry="${row.id}">View</button></div></div></article>`;}
function renderBanking(){const banks=bankAccounts(),cash=cashAccounts(),transfers=transferRows(),q=$('#bankAccountSearch').value.toLowerCase(),visible=[...cash,...banks].filter(row=>[row.name,row.bank_name,row.account_number,row.account_type].join(' ').toLowerCase().includes(q));$('#bankAccountList').innerHTML=visible.length?visible.map(row=>`<article class="record-card"><div class="record-top"><div><span class="record-id">${esc(row.account_type==='Cash'?'CASH ACCOUNT':row.bank_name||'BANK ACCOUNT')}</span><h3>${esc(row.name)}</h3><div class="record-meta">${row.account_type==='Cash'?'<span>Default cash ledger</span>':`<span>${row.account_number?`•••• ${esc(String(row.account_number).slice(-4))}`:'No account number'}</span>`}<span>${accountHasActivity(row.id)?'Active ledger':'No transactions'}</span></div></div><div class="record-side"><strong>${money(accountBalance(row.id))}</strong><button class="view-button" data-view-bank-account="${row.id}">View</button></div></div></article>`).join(''):empty('No accounts found','Cash is created automatically. Add a bank account when needed.');const withdrawals=transfers.filter(row=>account(row.from_account_id)?.account_type==='Bank'&&account(row.to_account_id)?.account_type==='Cash'),deposits=transfers.filter(row=>account(row.from_account_id)?.account_type==='Cash'&&account(row.to_account_id)?.account_type==='Bank'),bankMoves=transfers.filter(row=>account(row.from_account_id)?.account_type==='Bank'&&account(row.to_account_id)?.account_type==='Bank');$('#cashWithdrawalList').innerHTML=withdrawals.length?withdrawals.map(transferCard).join(''):empty('No cash withdrawals','Move money from a bank account to cash.');$('#cashDepositList').innerHTML=deposits.length?deposits.map(transferCard).join(''):empty('No cash deposits','Move cash into a bank account.');$('#bankTransferList').innerHTML=bankMoves.length?bankMoves.map(transferCard).join(''):empty('No bank transfers','Move money between two bank accounts.');const charges=state.payments.filter(row=>row.payment_type==='expense');$('#bankingExpenseChargeList').innerHTML=charges.length?charges.map(row=>{const cat=expenseCategory(row.expense_category_id||row.reference);return`<article class="record-card"><div class="record-top"><div><span class="record-id">${esc(row.payment_number||shortCode('EXP',row.id))}</span><h3>${esc(cat?.name||row.description)}</h3><div class="record-meta"><span>${date(row.payment_date)}</span><span>${esc(account(row.from_account_id)?.name||'Account')}</span><span>${esc(row.notes||'Business overhead')}</span></div></div><div class="record-side"><strong>${money(row.amount)}</strong><button class="view-button" data-view-banking-expense="${row.id}">View</button></div></div></article>`}).join(''):empty('No business expenses','Charge rent, salaries or other monthly overheads.');$('#bankingExpenseCategoryList').innerHTML=state.expenseCategories.length?state.expenseCategories.map(row=>`<article class="record-card"><div class="record-top"><div><span class="record-id">EXPENSE TYPE</span><h3>${esc(row.name)}</h3><div class="record-meta"><span>${esc(row.description||'No details')}</span></div></div><button class="view-button" data-view-expense-category="${row.id}">View</button></div></article>`).join(''):empty('No expense types','Add rent, salaries, equipment rental or another overhead.');}
function render(){renderParties();renderProjects();renderQuotes();renderInvoices();renderReceipts();renderLabour();renderMaterials();renderExpenses();renderOrders();renderPurchasing();renderLabourPayments();renderBanking();window.renderMobileReports?.();$('#quoteProjectOptions').innerHTML=state.projects.filter(r=>r.closed!==true).map(r=>`<option value="${esc(projectLabel(r))}"></option>`).join('');}

const approvedProjects=()=>state.projects.filter(r=>r.status==='Approved'&&r.closed!==true);
const projectReturnable=(projectId,materialId)=>Math.max(0,state.materialMovements.filter(row=>row.project_id===projectId&&row.material_id===materialId).reduce((total,row)=>total+(row.movement_type==='project_issue'?Number(row.quantity||0):row.movement_type==='project_return'?-Number(row.quantity||0):0),0));
function openParty(id=''){const r=party(id),next=id||uid();$('#partyForm').reset();$('#partyId').value=next;$('#partyCode').value=r?.party_number||nextSerial('PTY',state.parties,'party_number');$('#partyName').value=r?.name||'';$('#partyPhone').value=r?.phone||'';$('#partyAddress').value=r?.address||'';$('#partySheetTitle').textContent=r?'Edit party':'Add party';openSheet('#partySheet');}
function openProject(id=''){if(!state.parties.length){toast('Add a party before creating a project.');route('parties');return;}const r=project(id),next=id||uid();$('#projectForm').reset();$('#projectId').value=next;$('#projectCode').value=r?.project_number||nextSerial('PRJ',state.projects,'project_number');$('#projectName').value=r?.name||'';$('#projectParty').innerHTML=options(state.parties,row=>row.name,'Select party');$('#projectParty').value=r?.party_id||'';$('#projectLocation').value=r?.location||'';$('#projectClosed').checked=r?.closed===true;$('#projectSheetTitle').textContent=r?'Edit project':'Add project';openSheet('#projectSheet');}
const resolveParty=name=>state.parties.find(r=>r.name.toLowerCase()===name.trim().toLowerCase());
const resolveProject=label=>state.projects.find(r=>projectLabel(r).toLowerCase()===label.trim().toLowerCase());
function setQuoteDays(){$('#quoteDays').value=daysBetween($('#quoteStart').value,$('#quoteEnd').value);}
