function updatePayWageSummary(resetAmount=false){const workerId=$('#payWagesLabourer').value,rows=unpaidAssignments(workerId),gross=rows.reduce((sum,row)=>sum+assignmentOutstanding(row),0),advance=labourAdvanceAvailable(workerId),amountField=$('#payWagesAmount');if(resetAmount||Number(amountField.value)<=0||Number(amountField.value)>gross)amountField.value=gross?gross.toFixed(2):'';amountField.max=gross||'';const settle=Math.min(gross,Number(amountField.value||0)),applied=Math.min(settle,advance),cash=Math.max(0,settle-applied);$('#unpaidWageLines').innerHTML=rows.length?rows.map(row=>`<article class="wage-line"><div><b>${esc(labourTaskLabel(row))}</b><small>${date(row.assignment_date)} · ${qty(row.days)} day${Number(row.days)===1?'':'s'} × ${money(row.daily_rate)}</small></div><strong>${money(assignmentOutstanding(row))}</strong></article>`).join(''):empty('No unpaid wages','Choose another labour person.');$('#payWagesGross').textContent=money(gross);$('#payWagesAdvance').textContent=money(advance);$('#payWagesAccount').required=cash>0;$('#payWagesAccount').disabled=cash===0;$('#payWagesAccountLabel').classList.toggle('hidden',cash===0);$('#payWagesAccountHelp').textContent=cash>0?`${money(applied)} advance will be applied and ${money(cash)} will be paid from this account.`:`${money(applied)} will be settled from the available advance.`;}
