async function openBankingTransfer(mode){const banks=bankAccounts();if(!banks.length){toast('Add a bank account first.');route('bankAccounts');return;}if(mode==='bank'&&banks.length<2){toast('Add at least two bank accounts for a bank transfer.');route('bankAccounts');return;}let cash;try{cash=await ensureCashAccount();}catch(error){toast(error.message);return;}const config={withdraw:{title:'Withdraw cash',kicker:'BANK TO CASH',from:banks,to:[cash],fromLabel:'From bank *',toLabel:'To cash account *',details:'Cash withdrawal details'},deposit:{title:'Deposit cash',kicker:'CASH TO BANK',from:[cash],to:banks,fromLabel:'From cash account *',toLabel:'To bank *',details:'Cash deposit details'},bank:{title:'Bank to Bank transfer',kicker:'INTERNAL TRANSFER',from:banks,to:banks,fromLabel:'From bank *',toLabel:'To bank *',details:'Bank transfer details'}}[mode];$('#bankTransferForm').reset();$('#bankTransferMode').value=mode;$('#bankTransferDate').value=today();$('#bankTransferSheetTitle').textContent=config.title;$('#bankTransferKicker').textContent=config.kicker;$('#bankTransferFromLabel').childNodes[0].nodeValue=config.fromLabel;$('#bankTransferToLabel').childNodes[0].nodeValue=config.toLabel;$('#bankTransferFrom').innerHTML=options(config.from,row=>`${row.name}${row.bank_name?` - ${row.bank_name}`:''}`,'Select source account');$('#bankTransferTo').innerHTML=options(config.to,row=>`${row.name}${row.bank_name?` - ${row.bank_name}`:''}`,'Select destination account');if(config.from.length===1)$('#bankTransferFrom').value=config.from[0].id;if(config.to.length===1)$('#bankTransferTo').value=config.to[0].id;$('#bankTransferDetails').placeholder=config.details;updateTransferBalance();openSheet('#bankTransferSheet');}
function showBankingExpenseTab(name){$$('[data-banking-expense-tab]').forEach(button=>button.classList.toggle('active',button.dataset.bankingExpenseTab===name));$('#bankingExpenseChargesPanel').classList.toggle('active',name==='charges');$('#bankingExpenseListPanel').classList.toggle('active',name==='list');}
function openBankingExpense(){if(!state.expenseCategories.length){toast('Add an expense type first.');showBankingExpenseTab('list');return;}if(!state.paymentAccounts.length){toast('Add a bank or cash account first.');route('bankAccounts');return;}$('#bankingExpenseForm').reset();$('#bankingExpenseDate').value=today();$('#bankingExpenseCategory').innerHTML=options(state.expenseCategories,row=>row.name,'Select expense');$('#bankingExpenseAccount').innerHTML=options(state.paymentAccounts,row=>`${row.name}${row.bank_name?` - ${row.bank_name}`:''}`,'Select bank / cash account');openSheet('#bankingExpenseSheet');}

function detailRows(rows){return`<div class="detail-grid">${rows.map(([label,value])=>`<div class="detail-row"><span>${esc(label)}</span><b>${esc(value??'')}</b></div>`).join('')}</div>`;}
function setupDetail(type,row,{title,kicker,html,actions='',editable=true,deletable=true,documentName=''}){state.detail={type,id:row.id,documentName:documentName||`${type}-${row.id}`};$('#detailKicker').textContent=kicker;$('#detailTitle').textContent=title;$('#detailBody').innerHTML=html;$('#detailActions').innerHTML=actions;$('#detailEdit').classList.toggle('hidden',!editable);$('#dangerZone').classList.toggle('hidden',!deletable||state.role!=='owner');$('#detailDelete').textContent=`Delete ${type.replace(/([A-Z])/g,' $1').toLowerCase()}`;closeSheets();openSheet('#detailSheet');}
const detailCard=(eyebrow,title,amount,rows,pdf=false)=>`<article class="detail-card ${pdf?'pdf-document':''}"><div class="detail-hero"><p>${esc(eyebrow)}</p><h3>${esc(title)}</h3>${amount?`<div class="detail-amount">${esc(amount)}</div>`:''}</div>${detailRows(rows)}${pdf?businessContact():''}</article>`;
function viewParty(id){const r=party(id);if(r)setupDetail('party',r,{title:r.name,kicker:'PARTY DETAILS',html:detailCard(r.party_number||shortCode('PTY',r.id),r.name,'',[['Mobile number',r.phone],['Address',r.address]])});}
function viewProject(id){const r=project(id);if(r)setupDetail('project',r,{title:r.name,kicker:'PROJECT DETAILS',html:detailCard(r.project_number,r.name,'',[['Party',party(r.party_id)?.name],['Location',r.location],['Quote',r.quote_created?'Created':'Not created'],['Quote status',r.status],['Project status',r.closed?'Closed':'Active']])});}
const businessDocumentHeader=kind=>`<header class="document-header"><div class="document-brand"><p>${esc(kind)}</p><h2>${esc(PRINT_BUSINESS_NAME)}</h2></div><img src="assets/mughal-logo.png" alt="Company logo">${businessContact()}</header>`;
const projectDocumentHeader=(kind,number,job,documentDate)=>`${businessDocumentHeader(kind)}<section class="document-meta"><div><small>CUSTOMER</small><b>${esc(party(job.party_id)?.name||'')}</b><span>${esc(party(job.party_id)?.phone||'')}</span></div><div><small>PROJECT</small><b>${esc(job.name)}</b><span>${esc(job.location||'')}</span></div><div><small>DATE</small><b>${esc(date(documentDate))}</b></div><div><small>${kind.includes('INVOICE')?'INVOICE NO.':'QUOTE NO.'}</small><b>${esc(number)}</b></div></section>`;
const documentFooter=rows=>`<footer class="document-footer">${rows.map(([label,value])=>`<div><b>${esc(label)}</b><span>${esc(value??'')}</span></div>`).join('')}</footer>`;
function quoteDocument(r){const prices=r.pricing_mode==='both'?[['With material',r.price_with_material],['Without material',r.price_without_material]]:r.pricing_mode==='without_material'?[['Without material',r.price_without_material]]:[['With material',r.price_with_material]];return`<article class="detail-card pdf-document invoice-document quote-document">${projectDocumentHeader('PROJECT QUOTATION',r.project_number,r,r.quote_date)}<section class="document-table"><div class="document-table-head"><span>Project scope</span><span>Option</span><span>Amount</span></div>${prices.map(([label,value],index)=>`<div class="document-table-row"><span>${index===0?esc(r.description||''):''}</span><span>${esc(label)}</span><strong>${money(value)}</strong></div>`).join('')}</section>${documentFooter([['Project period',[date(r.start_date),date(r.expected_end_date)].filter(Boolean).join(' — ')],['Number of days',r.days_to_complete??''],['Payment terms',r.payment_terms],['Other details',r.notes],['Status',r.status]])}${disclaimerFooter()}</article>`;}
function viewQuote(id){const r=project(id);if(!r)return;const approved=r.status==='Approved';setupDetail('quote',r,{title:r.name,kicker:'QUOTE DETAILS',html:quoteDocument(r),actions:`<button class="button secondary block" data-detail-download>Download quote PDF</button>${approved?'':`<button class="button primary block" data-approve-quote="${r.id}">Approve quote</button>`}`,deletable:!approved,documentName:`quote-${r.project_number}`});}
function invoiceDocument(r){const job=project(r.project_id);if(!job)return'';const metric=projectMetrics(job),changes=metric.entries.filter(x=>['scope_increase','scope_decrease'].includes(x.entry_type)),lines=[['Original',job.description,metric.original],...changes.map(change=>[change.entry_type==='scope_increase'?'Addition':'Deduction',change.description,(change.entry_type==='scope_decrease'?-1:1)*Number(change.amount)])];return`<article class="detail-card pdf-document invoice-document project-invoice-document">${projectDocumentHeader('PROJECT INVOICE',r.invoice_number,job,r.invoice_date)}<section class="document-table"><div class="document-table-head"><span>Type</span><span>Project scope</span><span>Amount</span></div>${lines.map(([type,scope,amount])=>`<div class="document-table-row"><span>${esc(type)}</span><span>${esc(scope||'')}</span><strong class="${amount<0?'negative':''}">${amount<0?'− ':''}${money(Math.abs(amount))}</strong></div>`).join('')}<div class="document-total"><span>Invoice total</span><strong>${money(metric.revised)}</strong></div></section>${documentFooter([['Payment terms',job.payment_terms],['Other details',job.notes],['Project status',job.closed?'Closed':'Active']])}${disclaimerFooter()}</article>`;}
function viewInvoice(id){const r=state.invoices.find(x=>x.id===id);if(r)setupDetail('invoice',r,{title:r.invoice_number,kicker:'INVOICE DETAILS',html:invoiceDocument(r),actions:'<button class="button primary block" data-detail-download>Download invoice PDF</button>',editable:false,documentName:`invoice-${r.invoice_number}`});}
function viewReceipt(id){const r=state.payments.find(x=>x.id===id),job=project(r?.project_id);if(r)setupDetail('receipt',r,{title:r.payment_number||'Payment receipt',kicker:'RECEIVED PAYMENT',html:detailCard(`PAYMENT RECEIPT · ${r.payment_number||shortCode('RCP',r.id)}`,job?.name||'Project payment',money(r.amount),[['Business',PRINT_BUSINESS_NAME],['Party',party(r.party_id)?.name],['Project',job?.name],['Date',date(r.payment_date)],['Received in',account(r.to_account_id)?.name],['Details',r.description],['Notes',r.notes]],true),actions:'<button class="button primary block" data-detail-download>Download payment PDF</button>',documentName:`payment-${r.payment_number||r.id}`});}
function viewLabourPerson(id){const r=labourer(id);if(r)setupDetail('labourPerson',r,{title:r.name,kicker:'LABOUR PERSON',html:detailCard(r.labour_number||'WORKFORCE RECORD',r.name,`${money(r.daily_wage_rate)} / day`,[['Mobile number',r.mobile],['CNIC number',r.cnic],['Record date',date(r.record_date||r.created_at)],['Date of joining',date(r.joining_date)],['Speciality',r.speciality],['Status',r.active===false?'Inactive':'Active']])});}
function viewLabourWage(id){const r=state.labourWageSettlements.find(row=>row.id===id),worker=labourer(r?.labourer_id),items=state.labourWageSettlementItems.filter(row=>row.settlement_id===id),payment=state.payments.find(row=>row.id===r?.payment_id);if(r)setupDetail('labourWage',r,{title:worker?.name||'Wage payment',kicker:'WAGE SETTLEMENT',html:`${detailCard(date(r.settlement_date),worker?.name||'Labour',money(r.gross_wages),[['Unpaid wages settled',money(r.gross_wages)],['Advance adjusted',money(r.advance_applied)],['Paid from account',money(r.cash_paid)],['Account',r.cash_paid>0?account(payment?.from_account_id)?.name:'Advance only'],['Details',r.notes]])}<div class="scope-list"><h4>Paid assignments</h4>${items.map(item=>{const assignment=state.labourAssignments.find(row=>row.id===item.labour_assignment_id);return`<div class="scope-item"><div><b>${esc(assignment?labourTaskLabel(assignment):'Labour assignment')}</b><small>${date(assignment?.assignment_date)} · ${qty(assignment?.days)} day${Number(assignment?.days)===1?'':'s'}</small></div><strong>${money(item.amount)}</strong></div>`}).join('')}</div>`,editable:false,deletable:false});}
