function purchaseDocument(r){const vendor=supplier(r.supplier_id),lines=purchaseLines(r.id);return`<article class="detail-card pdf-document"><div class="detail-hero"><p>PURCHASE · ${esc(r.bill_number)}</p><h3>${esc(vendor?.name||'Supplier')}</h3><div class="detail-amount">${money(r.total_amount)}</div></div>${detailRows([['Business',PRINT_BUSINESS_NAME],['Supplier',vendor?.name],['Company',vendor?.company_name||vendor?.contact_name],['Purchase date',date(r.bill_date)],['Details',r.notes]])}<div class="order-line-list">${lines.map(line=>{const item=material(line.material_id);return`<div class="order-line-row"><div><b>${esc(item?.name||'Material')}</b><small>${qty(line.quantity)} ${esc(item?.unit||'units')} × ${money(line.unit_cost)}</small></div><strong>${money(line.line_total??Number(line.quantity)*Number(line.unit_cost))}</strong></div>`}).join('')}</div>${detailRows([['Subtotal',money(r.subtotal??Number(r.total_amount)+Number(r.discount||0))],['Discount',`− ${money(r.discount)}`],['Grand total',money(r.total_amount)],['Amount paid',money(r.amount_paid)],['Balance due',money(purchaseDue(r))],['Payment status',r.payment_status]])}${businessContact()}</article>`;}
