$('#purchaseForm').addEventListener('submit',async e=>{e.preventDefault();const items=readPurchaseLines(),discount=Number($('#purchaseDiscount').value||0),subtotal=items.reduce((sum,line)=>sum+lineAmount(line.quantity,line.unit_cost),0),total=subtotal-discount;if(items.some(line=>!line.material_id||!(line.quantity>0)||!(line.unit_cost>0))){toast('Complete every material, quantity and rate.');return}if(discount<0||discount>subtotal||total<=0){toast('Discount must be between zero and the subtotal.');return}const payload={p_supplier_id:$('#purchaseSupplier').value,p_bill_date:$('#purchaseDate').value,p_notes:$('#purchaseDetails').value.trim()||null,p_discount:discount,p_items:items};try{await working('Saving purchase and updating stock…',e.submitter,async()=>{let billId;if(cloud){billId=await store.rpc('create_purchase_bill_mobile',payload);await store.load()}else{billId=uid();const vendor=supplier(payload.p_supplier_id),bill={id:billId,business_id:state.businessId,supplier_id:payload.p_supplier_id,bill_number:`MIPB-${new Date().getFullYear()}-${String(Date.now()).slice(-6)}`,bill_date:payload.p_bill_date,subtotal,discount,total_amount:total,amount_paid:0,payment_status:'Unpaid',status:'Posted',notes:payload.p_notes,created_at:new Date().toISOString()};state.purchaseBills.unshift(bill);items.forEach(line=>{const itemRow={id:uid(),business_id:state.businessId,purchase_bill_id:billId,line_total:lineAmount(line.quantity,line.unit_cost),created_at:new Date().toISOString(),...line};state.purchaseBillItems.push(itemRow);state.materialMovements.unshift({id:uid(),business_id:state.businessId,material_id:line.material_id,movement_type:'purchase',movement_date:payload.p_bill_date,quantity:line.quantity,unit_cost:line.unit_cost,supplier_id:vendor.id,supplier_name:vendor.name,reference:bill.bill_number,purchase_bill_id:billId,purchase_bill_item_id:itemRow.id,created_at:new Date().toISOString()})})}store.persist();closeSheets();render();viewPurchase(billId);toast('Purchase saved and material stock updated.')})}catch{}});
$('#purchasePaymentForm').addEventListener('submit',async e=>{e.preventDefault();const supplierId=$('#purchasePaymentSupplier').value,amount=Number($('#purchasePaymentAmount').value),vendor=supplier(supplierId);if(!vendor){toast('Select a supplier.');return}const payload={p_business_id:state.businessId,p_supplier_id:supplierId,p_payment_date:$('#purchasePaymentDate').value,p_from_account_id:$('#purchasePaymentAccount').value,p_amount:amount,p_description:$('#purchasePaymentDetails').value.trim()||`Supplier payment - ${vendor.name}`};try{await working('Saving supplier payment…',e.submitter,async()=>{if(cloud){await store.rpc('record_supplier_payment',payload);await store.load()}else{state.payments.unshift({id:uid(),payment_number:`MIT-${Date.now().toString().slice(-7)}`,payment_type:'supplier_payment',payment_date:payload.p_payment_date,from_account_id:payload.p_from_account_id,to_account_id:null,supplier_id:supplierId,purchase_bill_id:null,description:payload.p_description,amount,created_at:new Date().toISOString()});let remaining=amount;const bills=state.purchaseBills.filter(row=>row.supplier_id===supplierId&&row.status==='Posted').sort((a,b)=>`${a.bill_date}${a.created_at||''}`.localeCompare(`${b.bill_date}${b.created_at||''}`));for(const bill of bills){if(remaining<=0)break;const applied=Math.min(remaining,Math.max(0,purchaseBalance(bill)));bill.amount_paid=Number(bill.amount_paid||0)+applied;remaining-=applied;bill.payment_status=bill.amount_paid>=Number(bill.total_amount)?'Paid':'Partly Paid'}if(remaining>0&&bills.length){const bill=bills[bills.length-1];bill.amount_paid=Number(bill.amount_paid||0)+remaining;bill.payment_status='Paid'}}store.persist();closeSheets();render();toast('Supplier payment saved.')})}catch{}});

