$('#bankTransferForm').addEventListener('submit',async e=>{e.preventDefault();const mode=$('#bankTransferMode').value,from=account($('#bankTransferFrom').value),to=account($('#bankTransferTo').value),amount=Number($('#bankTransferAmount').value);if(!from||!to){toast('Select both transfer accounts.');return}if(from.id===to.id){toast('Source and destination accounts must be different.');return}const valid=mode==='withdraw'?from.account_type==='Bank'&&to.account_type==='Cash':mode==='deposit'?from.account_type==='Cash'&&to.account_type==='Bank':from.account_type==='Bank'&&to.account_type==='Bank';if(!valid){toast('The selected accounts do not match this transfer type.');return}if(amount>accountBalance(from.id)){toast(`Only ${money(accountBalance(from.id))} is available in ${from.name}.`);return}const payload={p_business_id:state.businessId,p_payment_type:'transfer',p_payment_date:$('#bankTransferDate').value,p_from_account_id:from.id,p_to_account_id:to.id,p_party_id:null,p_supplier_id:null,p_project_id:null,p_walk_in_order_id:null,p_purchase_bill_id:null,p_invoice_id:null,p_description:$('#bankTransferDetails').value.trim(),p_amount:amount,p_reference:null,p_notes:null};try{await working('Saving money transfer…',e.submitter,async()=>{if(cloud){await store.rpc('record_payment',payload);await store.load()}else state.payments.unshift({id:uid(),business_id:state.businessId,payment_number:`MIT-${Date.now().toString().slice(-7)}`,payment_type:'transfer',payment_date:payload.p_payment_date,from_account_id:from.id,to_account_id:to.id,description:payload.p_description,amount,created_at:new Date().toISOString()});store.persist();closeSheets();render();toast(mode==='withdraw'?'Cash withdrawal saved.':mode==='deposit'?'Cash deposit saved.':'Bank transfer saved.')})}catch{}});
$('#bankingExpenseForm').addEventListener('submit',async e=>{e.preventDefault();const cat=expenseCategory($('#bankingExpenseCategory').value),from=account($('#bankingExpenseAccount').value),amount=Number($('#bankingExpenseAmount').value);if(!cat||!from){toast('Select an expense and payment account.');return}if(amount>accountBalance(from.id)){toast(`Only ${money(accountBalance(from.id))} is available in ${from.name}.`);return}const payload={p_business_id:state.businessId,p_payment_type:'expense',p_payment_date:$('#bankingExpenseDate').value,p_from_account_id:from.id,p_to_account_id:null,p_party_id:null,p_supplier_id:null,p_project_id:null,p_walk_in_order_id:null,p_purchase_bill_id:null,p_invoice_id:null,p_description:cat.name,p_amount:amount,p_reference:cat.id,p_notes:$('#bankingExpenseDetails').value.trim()||null};try{await working('Charging business expense…',e.submitter,async()=>{if(cloud){await store.rpc('record_payment',payload);await store.load()}else state.payments.unshift({id:uid(),business_id:state.businessId,payment_number:`MIT-${Date.now().toString().slice(-7)}`,payment_type:'expense',payment_date:payload.p_payment_date,from_account_id:from.id,to_account_id:null,expense_category_id:cat.id,description:cat.name,reference:cat.id,notes:payload.p_notes,amount,created_at:new Date().toISOString()});store.persist();closeSheets();render();showBankingExpenseTab('charges');toast('Business expense charged.')})}catch{}});

$('#payAdvanceForm').addEventListener('submit',async e=>{e.preventDefault();const existing=state.payments.find(row=>row.id===$('#payAdvanceId').value),payload={p_business_id:state.businessId,p_labourer_id:existing?.labourer_id||$('#payAdvanceLabourer').value,p_payment_date:$('#payAdvanceDate').value,p_from_account_id:$('#payAdvanceAccount').value,p_amount:Number($('#payAdvanceAmount').value),p_description:$('#payAdvanceDetails').value.trim()||'Labour advance'};try{await working(existing?'Updating labour advance…':'Paying labour advance…',e.submitter,async()=>{if(cloud){if(existing)await store.rpc('update_labour_advance',{p_payment_id:existing.id,p_payment_date:payload.p_payment_date,p_from_account_id:payload.p_from_account_id,p_amount:payload.p_amount,p_description:payload.p_description});else await store.rpc('record_labour_advance',payload);await store.load()}else if(existing)Object.assign(existing,{payment_date:payload.p_payment_date,from_account_id:payload.p_from_account_id,amount:payload.p_amount,description:payload.p_description});else state.payments.unshift({id:uid(),business_id:state.businessId,payment_number:`MIT-${Date.now().toString().slice(-7)}`,payment_type:'labour_advance',payment_date:payload.p_payment_date,from_account_id:payload.p_from_account_id,labourer_id:payload.p_labourer_id,description:payload.p_description,amount:payload.p_amount,created_at:new Date().toISOString()});store.persist();closeSheets();render();toast(existing?'Labour advance updated.':'Labour advance paid.')})}catch{}});
$('#payWagesForm').addEventListener('submit',async e=>{e.preventDefault();const labourerId=$('#payWagesLabourer').value,assignments=unpaidAssignments(labourerId),due=labourUnpaidTotal(labourerId),amount=Number($('#payWagesAmount').value),advance=Math.min(amount,labourAdvanceAvailable(labourerId)),cash=Math.max(0,amount-advance),accountId=$('#payWagesAccount').value||null;if(!assignments.length){toast('There are no unpaid assignments for this labour person.');return}if(!(amount>0)||amount>due+.005){toast(`Enter an amount up to ${money(due)}.`);return}if(cash>0&&!accountId){toast('Select the account paying the remaining wages.');return}const payload={p_business_id:state.businessId,p_labourer_id:labourerId,p_settlement_date:$('#payWagesDate').value,p_from_account_id:accountId,p_notes:$('#payWagesDetails').value.trim()||null,p_assignment_ids:assignments.map(row=>row.id),p_amount:amount};try{await working('Saving wage payment…',e.submitter,async()=>{if(cloud){await store.rpc('settle_labour_wages',payload);await store.load()}else{const settlementId=uid(),paymentId=cash>0?uid():null;state.labourWageSettlements.unshift({id:settlementId,business_id:state.businessId,labourer_id:labourerId,settlement_date:payload.p_settlement_date,gross_wages:amount,advance_applied:advance,cash_paid:cash,payment_id:paymentId,notes:payload.p_notes,created_at:new Date().toISOString()});let remaining=amount;for(const row of assignments){if(remaining<=.005)break;const applied=Math.min(remaining,assignmentOutstanding(row));state.labourWageSettlementItems.unshift({id:uid(),business_id:state.businessId,settlement_id:settlementId,labour_assignment_id:row.id,amount:applied,created_at:new Date().toISOString()});remaining-=applied}if(paymentId)state.payments.unshift({id:paymentId,business_id:state.businessId,payment_number:`MIT-${Date.now().toString().slice(-7)}`,payment_type:'labour_payment',payment_date:payload.p_settlement_date,from_account_id:accountId,labourer_id:labourerId,description:payload.p_notes||'Labour wage payment',amount:cash,created_at:new Date().toISOString()})}store.persist();closeSheets();render();toast('Wage payment saved.')})}catch{}});
$('#disclaimerForm').addEventListener('submit',async e=>{e.preventDefault();const value=$('#disclaimerText').value.trim();if(!value){toast('Enter disclaimer text.');return}try{await working('Saving print disclaimer…',e.submitter,async()=>{state.business=await store.updateBusiness({document_disclaimer:value});store.persist();closeSheets();render();const detail=state.detail;if(detail?.type==='quote')viewQuote(detail.id);else if(detail?.type==='invoice')viewInvoice(detail.id);else if(detail?.type==='orderInvoice')viewOrderInvoice(detail.id);toast('Disclaimer updated.')})}catch{}});

async function deleteDetail(button){
  const {type,id}=state.detail||{};if(!type)return;
  const messages={party:'Delete this party? This cannot be undone.',project:'Delete this project? This cannot be undone.',quote:'Delete this quote? The project record will remain.',invoice:'Delete this invoice? The quote will return to Pending.',receipt:'Delete this received payment? Its project receipt entry will also be removed.',labourPerson:'Delete this labour person? This cannot be undone.',expenseCategory:'Delete this expense type? This cannot be undone.',orderInvoice:'Delete this order invoice? This is only allowed before receipts, expenses, material or labour are recorded.',orderReceipt:'Delete this received payment? Its order receipt entry will also be removed.',orderItem:'Delete this invoice item? Existing saved invoices will keep their item details.',supplier:'Delete this supplier? This is only allowed before purchases are recorded.',purchaseMaterial:'Delete this material? This is only allowed before purchases or assignments are recorded.'};
  if(!confirm(messages[type]||'Delete this record? This cannot be undone.'))return;
  try{await working(`Deleting ${type}…`,button,async()=>{
    if(type==='party'){await store.remove('parties',id);state.parties=state.parties.filter(r=>r.id!==id)}
    if(type==='project'){const row=project(id);if(row.quote_created||state.entries.some(e=>e.project_id===id)||state.invoices.some(i=>i.project_id===id))throw new Error('Delete its quote, invoice and project activity before deleting this project.');await store.remove('projects',id);state.projects=state.projects.filter(r=>r.id!==id)}
    if(type==='quote'){const row=project(id);if(row.status==='Approved')throw new Error('Delete the invoice first before deleting an approved quote.');upsert(state.projects,await store.save('projects',{id,description:null,start_date:null,expected_end_date:null,days_to_complete:null,price_with_material:null,price_without_material:null,payment_terms:null,notes:null,pricing_mode:'with_material',quote_created:false,status:'Pending',updated_at:new Date().toISOString()},true))}
    if(type==='invoice'){const invoice=state.invoices.find(r=>r.id===id);await store.remove('invoices',id);state.invoices=state.invoices.filter(r=>r.id!==id);const job=project(invoice.project_id);if(job)upsert(state.projects,await store.save('projects',{id:job.id,status:'Pending',original_contract_amount:0,updated_at:new Date().toISOString()},true))}
    if(type==='receipt'){if(cloud)await store.rpc('delete_project_receipt',{p_payment_id:id});state.payments=state.payments.filter(r=>r.id!==id);state.entries=state.entries.filter(r=>r.payment_id!==id)}
    if(type==='labourPerson'){await store.remove('labourers',id);state.labourers=state.labourers.filter(r=>r.id!==id)}
    if(type==='expenseCategory'){await store.remove('expense_categories',id);state.expenseCategories=state.expenseCategories.filter(r=>r.id!==id)}
    if(type==='orderInvoice'){if(cloud)await store.rpc('delete_order_invoice',{p_order_id:id});else{const hasActivity=state.walkInEntries.some(r=>r.walk_in_order_id===id)||state.materialMovements.some(r=>r.walk_in_order_id===id)||state.labourAssignments.some(r=>r.walk_in_order_id===id);if(hasActivity)throw new Error('Delete order activity before deleting this invoice.');state.walkInOrders=state.walkInOrders.filter(r=>r.id!==id);state.invoices=state.invoices.filter(r=>r.walk_in_order_id!==id);state.orderInvoiceItems=state.orderInvoiceItems.filter(r=>r.walk_in_order_id!==id)}}
    if(type==='orderReceipt'){if(cloud)await store.rpc('delete_order_receipt',{p_payment_id:id});state.payments=state.payments.filter(r=>r.id!==id);state.walkInEntries=state.walkInEntries.filter(r=>r.payment_id!==id)}
    if(type==='orderItem'){await store.remove('order_items',id);state.orderItems=state.orderItems.filter(r=>r.id!==id)}
    if(type==='supplier'){if(state.purchaseBills.some(r=>r.supplier_id===id))throw new Error('This supplier has purchase records and cannot be deleted.');await store.remove('suppliers',id);state.suppliers=state.suppliers.filter(r=>r.id!==id)}
    if(type==='purchaseMaterial'){if(state.materialMovements.some(r=>r.material_id===id)||state.purchaseBillItems.some(r=>r.material_id===id))throw new Error('This material has stock activity and cannot be deleted.');await store.remove('materials',id);state.materials=state.materials.filter(r=>r.id!==id)}
    if(cloud&&['orderInvoice','orderReceipt'].includes(type))await store.load();store.persist();closeSheets();render();toast('Record deleted.');
  })}catch{}
}
const viewHandlers={'party':viewParty,'project':viewProject,'quote':viewQuote,'invoice':viewInvoice,'receipt':viewReceipt,'labour-person':viewLabourPerson,'labour-assignment':viewLabourAssignment,'labour-wage':viewLabourWage,'labour-advance':viewLabourAdvance,'material-assignment':viewMaterialAssignment,'expense-category':viewExpenseCategory,'expense-charge':viewExpenseCharge,'order-invoice':viewOrderInvoice,'order-receipt':viewOrderReceipt,'order-expense':viewOrderExpense,'order-material':viewOrderMaterial,'order-labour':viewOrderLabour,'order-item':viewOrderItem,'supplier':viewSupplier,'purchase-material':viewPurchaseMaterial,'purchase':viewPurchase,'purchase-payment':viewPurchasePayment,'bank-account':viewBankAccount,'bank-transfer-entry':viewBankTransferEntry,'banking-expense':viewBankingExpense};
document.addEventListener('click',async e=>{
  const routeButton=e.target.closest('[data-route]');if(routeButton)route(routeButton.dataset.route);
  const orderRouteButton=e.target.closest('[data-order-route]');if(orderRouteButton)route(orderRouteButton.dataset.orderRoute);
  const purchaseRouteButton=e.target.closest('[data-purchase-route]');if(purchaseRouteButton)route(purchaseRouteButton.dataset.purchaseRoute);
  const bankingRouteButton=e.target.closest('[data-banking-route]');if(bankingRouteButton)route(bankingRouteButton.dataset.bankingRoute);
  const tabButton=e.target.closest('[data-tab]');if(tabButton)tab(tabButton.dataset.tab);
  if(e.target.closest('[data-close]')||e.target.id==='backdrop')closeSheets();
  const action=e.target.closest('[data-action]')?.dataset.action;
  ({'add-party':openParty,'add-project':openProject,'add-quote':openQuote,'scope-change':openScope,'add-receipt':openReceipt,'add-labour-person':openLabourPerson,'assign-labour':openLabourAssignment,'assign-material':()=>openMaterialAssignment('assign'),'return-material':()=>openMaterialAssignment('return'),'add-expense':openExpenseCategory,'charge-expense':openExpenseCharge,'add-order-invoice':openOrderInvoice,'add-order-receipt':openOrderReceipt,'charge-order-expense':openOrderExpense,'assign-order-material':()=>openOrderMaterial('assign'),'return-order-material':()=>openOrderMaterial('return'),'assign-order-labour':openOrderLabour,'add-order-item':openOrderItem,'add-supplier':openSupplier,'add-purchase-material':openPurchaseMaterial,'add-purchase':openPurchase,'add-purchase-payment':openPurchasePayment,'pay-wages':openPayWages,'pay-advance':openPayAdvance,'add-bank-account':openBankAccount,'withdraw-cash':()=>openBankingTransfer('withdraw'),'deposit-cash':()=>openBankingTransfer('deposit'),'bank-transfer':()=>openBankingTransfer('bank'),'charge-banking-expense':openBankingExpense}[action]||(()=>{}))();
  const projectAction=e.target.closest('[data-project-action]');if(projectAction)route({receipt:'receipts',labour:'labour',material:'materials',expense:'expenses'}[projectAction.dataset.projectAction]);
  const labourTab=e.target.closest('[data-labour-tab]');if(labourTab)showLabourTab(labourTab.dataset.labourTab);
  const expenseTab=e.target.closest('[data-expense-tab]');if(expenseTab)showExpenseTab(expenseTab.dataset.expenseTab);
  const orderExpenseTab=e.target.closest('[data-order-expense-tab]');if(orderExpenseTab)showOrderExpenseTab(orderExpenseTab.dataset.orderExpenseTab);
  const orderLabourTab=e.target.closest('[data-order-labour-tab]');if(orderLabourTab)showOrderLabourTab(orderLabourTab.dataset.orderLabourTab);
  const bankingExpenseTab=e.target.closest('[data-banking-expense-tab]');if(bankingExpenseTab)showBankingExpenseTab(bankingExpenseTab.dataset.bankingExpenseTab);
  const payWorker=e.target.closest('[data-pay-worker]');if(payWorker)openPayWages(payWorker.dataset.payWorker);
  const removeOrderLine=e.target.closest('[data-remove-order-line]');if(removeOrderLine){const lines=$$('.invoice-line',$('#orderInvoiceLines'));if(lines.length===1)toast('An invoice needs at least one item.');else{removeOrderLine.closest('.invoice-line').remove();recalcOrderInvoice();}}
  const removePurchaseLine=e.target.closest('[data-remove-purchase-line]');if(removePurchaseLine){const lines=$$('.purchase-line',$('#purchaseLines'));if(lines.length===1)toast('A purchase needs at least one material.');else{removePurchaseLine.closest('.purchase-line').remove();recalcPurchase();}}
  for(const [name,handler] of Object.entries(viewHandlers)){const button=e.target.closest(`[data-view-${name}]`);if(button){handler(button.getAttribute(`data-view-${name}`));break}}
  const approve=e.target.closest('[data-approve-quote]');if(approve)openApproval(approve.dataset.approveQuote);
  const download=e.target.closest('[data-detail-download]');if(download)try{await downloadCurrent(download)}catch{}
  const editDisclaimer=e.target.closest('[data-edit-disclaimer]');if(editDisclaimer){e.preventDefault();e.stopPropagation();openDisclaimerEditor();return;}
  const disclaimer=e.target.closest('[data-toggle-disclaimer]');if(disclaimer){const expanded=disclaimer.getAttribute('aria-expanded')==='true';disclaimer.setAttribute('aria-expanded',String(!expanded));disclaimer.closest('[data-disclaimer]')?.classList.toggle('expanded',!expanded);}
  const listDownload=e.target.closest('[data-download-invoice]');if(listDownload){viewInvoice(listDownload.dataset.downloadInvoice);try{await downloadCurrent($('[data-detail-download]'))}catch{}}
  if(e.target.id==='detailDelete')await deleteDetail(e.target);
  if(e.target.id==='detailEdit'){const d=state.detail;closeSheets();if(d.type==='party')openParty(d.id);if(d.type==='project')openProject(d.id);if(d.type==='quote')openQuote(d.id);if(d.type==='receipt')openReceipt(d.id);if(d.type==='labourPerson')openLabourPerson(d.id);if(d.type==='labourAdvance')openPayAdvance(d.id);if(d.type==='expenseCategory')openExpenseCategory(d.id);if(d.type==='orderInvoice')openOrderInvoice(d.id);if(d.type==='orderReceipt')openOrderReceipt(d.id);if(d.type==='orderItem')openOrderItem(d.id);if(d.type==='supplier')openSupplier(d.id);if(d.type==='purchaseMaterial')openPurchaseMaterial(d.id);if(d.type==='bankAccount')openBankAccount(d.id)}
});
